<?php if(!empty($sms_review)):$master=$sms_review['settings'];$documentLinks=function($kind,$reference)use($sms_review,$h){foreach($sms_review['documents'] as $doc)if($doc['kind']===$kind && (int)$doc['reference_id']===(int)$reference)echo '<a href="'.base_url('communications_admin/document/'.(int)$doc['id']).'">'.$h(ucfirst($doc['slot'])).' · '.$h($doc['filename']).'</a><br>';}; ?>
<section class="comm-card"><h2>Master settings · bank payments and SMS identity</h2><p class="muted">The bank account is shown on Fleet manual-credit screens. Shared-only uses one platform sender; hybrid permits requests for approved business senders. The selected provider must approve any sender before use. Leaving the shared sender blank keeps the sender configured in the Central SMS provider settings.</p>
<?php $open('sms_master'); ?><div class="comm-split"><label>Bank name<input name="bank_name" maxlength="100" value="<?= $h($master['bank_name']); ?>"></label><label>Account name<input name="bank_account_name" maxlength="190" value="<?= $h($master['bank_account_name']); ?>"></label><label>Account number<input name="bank_account_number" inputmode="numeric" pattern="[0-9]{10}" maxlength="10" value="<?= $h($master['bank_account_number']); ?>"></label><label>Sender ID policy<select name="sender_mode"><option value="shared" <?= $master['sender_mode']==='shared'?'selected':''; ?>>Shared sender only</option><option value="hybrid" <?= $master['sender_mode']==='hybrid'?'selected':''; ?>>Shared + approved custom senders</option></select></label><label>Approved shared Sender ID (optional override)<input name="shared_sender" maxlength="11" value="<?= $h($master['shared_sender']); ?>"></label></div><button class="btn" style="margin-top:15px">Save master settings</button><?= form_close(); ?></section>
<details class="comm-card"><summary>Credit bundles · explicit price and quantity</summary><p class="muted">Use bundles for volume prices, such as a fixed amount for 1,000 emails or 5,000 SMS pages. The base per-credit rate applies to custom top-ups. Editing a bundle changes new requests only. No suggested commercial rates are published automatically.</p>
<?php $bundles=$sms_review['bundles'];$bundles[]=array('id'=>0,'channel'=>'sms','name'=>'','amount_kobo'=>0,'credit_units'=>1000,'enabled'=>1);foreach($bundles as $bundle):$open('credit_bundle',array('package_id'=>$bundle['id'])); ?><h3><?= $bundle['id']?$h($bundle['name']):'Create a bundle'; ?></h3><div class="comm-split"><label>Channel<select name="module_key" <?= $bundle['id']?'disabled':''; ?>><option value="sms" <?= $bundle['channel']==='sms'?'selected':''; ?>>SMS pages</option><option value="email" <?= $bundle['channel']==='email'?'selected':''; ?>>Email recipients</option></select><?php if($bundle['id']): ?><input type="hidden" name="module_key" value="<?= $h($bundle['channel']); ?>"><?php endif; ?></label><label>Name<input name="name" maxlength="100" value="<?= $h($bundle['name']); ?>" required></label><label>Price (NGN)<input name="amount" type="number" min="100" max="500000" step="0.01" value="<?= $bundle['amount_kobo']?$h($bundle['amount_kobo']/100):''; ?>" required></label><label>Credits<input name="credit_units" type="number" min="1" max="10000000" value="<?= (int)$bundle['credit_units']; ?>" required></label></div><label class="choice"><input name="enabled" type="checkbox" value="1" <?= $bundle['enabled']?'checked':''; ?>> Publish bundle</label><button class="btn secondary" style="margin:12px 0 20px">Save bundle</button><?= form_close(); ?><?php endforeach; ?></details>
<section class="comm-card"><h2>Custom Sender ID review</h2><p class="muted">Download the private documents and submit them through the selected provider's registration process. Approve only after confirming provider/network activation; record the confirmation reference. Approval emails and document requests use the platform notification lane.</p><div class="comm-scroll"><table class="comm-table"><thead><tr><th>Account / Sender ID</th><th>Business / example</th><th>Documents</th><th>Status / review</th></tr></thead><tbody><?php foreach($sms_review['requests'] as $r): ?><tr><td><a href="<?= base_url('communications_admin?account='.(int)$r['account_id']).$suffix; ?>">Account #<?= (int)$r['account_id']; ?></a><br><b><?= $h($r['sender_id']); ?></b><br><?= $h($r['contact_email']); ?></td><td><?= $h($r['business_name']); ?><br><?= $h($r['sample_message']); ?></td><td><?php $documentLinks('sender',$r['id']); ?></td><td><b><?= $h(ucfirst($r['status'])); ?></b><p class="muted"><?= $h($r['note']); ?></p><?php if(in_array($r['status'],array('pending','approved'),true)):$open('sender_review',array('request_id'=>$r['id'],'account_id'=>$r['account_id'])); ?><label>Provider confirmation / reason<input name="note" minlength="5" maxlength="500" required></label><div class="row"><?php if($r['status']==='pending'): ?><button class="btn" name="status" value="approved">Provider approved · activate</button><button class="btn secondary" name="status" value="rejected">Reject</button><?php else: ?><button class="btn secondary" name="status" value="revoked">Revoke custom sender</button><?php endif; ?></div><?= form_close(); ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$sms_review['requests']): ?><p class="empty">No Sender ID requests.</p><?php endif; ?></section>
<?php endif; ?>
